function grid$dmhogiadinh(f){
  this.constructor(f);
}
grid$dmhogiadinh.prototype = new DirEvent();
grid$dmhogiadinh.prototype.cellFocus = function(o){
  DirEvent.prototype.cellFocus.apply(this, arguments);
  this.reloadInvGrid(o);
}
grid$dmhogiadinh.prototype.beforeInit = function(renderType){
  var p = this._dir;
  if (renderType == 0) {
    $("<div>").addClass('bottom-resize').attr('id', 'bar_resize_grid').appendTo($("#content"))
    p.options.renderCompleted = function() {
      var g = p.grid(), dt = g.data, m = new Memvars(), r = (dt.count() > 0)? 0: null;
	  var dataValue = (dt.count() <= 0) ? 0 : 1;

      if (r !== null){
	  	m.add([['xu_ly', 'I', 1], ['ma_hogiadinh', 'C', dt.val(r, 'ma_hogiadinh')], ['ma_ttp', 'C', dt.val(r, 'ma_ttp')], ['ma_phuongxa', 'C', dt.val(r, 'ma_phuongxa')], ['ma_khupho', 'C', dt.val(r, 'ma_khupho')], ['dia_chi', 'C', dt.val(r, 'dia_chi')], ['unit_id', 'I', dt.val(r, 'unit_id')], ['data', 'I', dataValue]]);
        p.options._currentCode = dt.val(r, 'ma_hogiadinh') + '#' + dt.val(r, 'id');
      }
      else {
		m.add([['xu_ly', 'I', 1], ['ma_hogiadinh', 'C', ''], ['ma_ttp', 'C', ''], ['ma_phuongxa', 'C', ''], ['ma_khupho', 'C', ''], ['ma_khupho', 'C', ''], ['dia_chi', 'C', ''], ['unit_id', 'I', 0], ['data', 'I', dataValue]]);
        p.options._currentCode = '#'
      }

      p.options._dirHD = $.createDir(false, { controller: "qldctcccd_1", memvars: m, focusWhenCreated: false, applyShortWhenCreated: false, folder: "Grid", dirViewType: "",subtitle:"", dirAbove: p, renderCompleted: function() {
        var gridDir = $("#content").find(".dir");
        var oG1Resize = $(gridDir.get(0));
        var oG2Resize = $(gridDir.get(1));
        $("#bar_resize_grid").boxresize({ divBox1: oG1Resize, divBox2: oG2Resize, resizeWidth: false});
      } });
      p.options.renderCompleted = null;
    }
  }
}
grid$dmhogiadinh.prototype.afterInit = function(renderType){
  var p = this._dir, phd = p.options._dirHD, m = new Memvars(), g = p.grid(), dt = g.data;

  if (renderType == 0) {
    var wHeight = $(window).height(), hBar = 70;
    if($(window).width() < 767)
      hBar = 60;
    $("#content").css("height", (wHeight - hBar) + "px");
  } else {

	if(dt.count() <= 0) {
		this.reloadInvGridNull();
	} else {
	    p.options._currentCode = '#';
		this.reloadInvGrid();
	}
  }
}
grid$dmhogiadinh.prototype.selectItemChanged = function(dt){
  var p = this._dir;
  this.reloadInvGrid();
}
grid$dmhogiadinh.prototype.reloadInvGrid = function(){
  var p = this._dir, phd = p.options._dirHD, m = phd.options.memvars, g = p.grid(), r = g._currRow||0, dt = g.data, curr = dt.val(r, 'ma_hogiadinh') + '#' + + dt.val(r, 'ma_chuho');
  if (phd && dt.count() > 0 && curr != p.options._currentCode) {
	m.add([['xu_ly', 'I', 1], ['ma_hogiadinh', 'C', dt.val(r, 'ma_hogiadinh')], ['ma_ttp', 'C', dt.val(r, 'ma_ttp')], ['ma_phuongxa', 'C', dt.val(r, 'ma_phuongxa')], ['ma_khupho', 'C', dt.val(r, 'ma_khupho')], ['dia_chi', 'C', dt.val(r, 'dia_chi')], ['unit_id', 'I', dt.val(r, 'unit_id')], ['data', 'I', 1]]);
    p.options._currentCode = curr;
    phd._refresh();
  }
}
grid$dmhogiadinh.prototype.reloadInvGridNull = function(){
  var p = this._dir, phd = p.options._dirHD, m = phd.options.memvars, g = p.grid(), r = g._currRow||0, dt = g.data;
  var dataValue = (dt.count() <= 0) ? 0 : 1;
	m.add([['xu_ly', 'I', 1], ['ma_hogiadinh', 'C', ''], ['ma_ttp', 'C', ''], ['ma_phuongxa', 'C', ''], ['ma_khupho', 'C', ''], ['ma_khupho', 'C', ''], ['dia_chi', 'C', ''], ['unit_id', 'I', 0], ['data', 'I', dataValue]]);
	phd._refresh();
}
grid$dmhogiadinh.prototype.beforeButtonGridClick = function (id, gindex, r) {
  var p = this._dir, g = p.grid(), dt = g.data;
  switch (id) {
    case 'refresh':
	if(dt.count() > 0) {
      p.options._currentCode = '#';
      this.reloadInvGrid();
	}
    default:
      break;
  }
  return true;
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 50%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
